import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace, createForks } from "@tigrisdata/agent-kit";
import { put, get } from "@tigrisdata/storage";

async function main() {
  try {
    // 1. Read trial_id
    const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
    const trialId = trialIdRaw.trim().toLowerCase().replace(/_/g, "-");

    // 2. Build the editor workspace name
    const workspaceName = `harbor-ro-${trialId}`;

    // 3. Call createWorkspace
    console.log(`Creating workspace: ${workspaceName}`);
    const { data: wsData, error: wsError } = await createWorkspace(workspaceName, {
      ttl: { days: 1 },
      enableSnapshots: true,
      credentials: { role: "Editor" }
    });

    if (wsError || !wsData || !wsData.credentials) {
      console.error("Failed to create workspace:", wsError);
      process.exit(1);
    }

    const editorCreds = wsData.credentials;
    const editorBucket = wsData.bucket;

    console.log(`Workspace created. Bucket: ${editorBucket}`);

    // 4. Write notes/welcome.txt using editor credentials
    console.log("Writing notes/welcome.txt with editor credentials");
    const { error: putError } = await put("notes/welcome.txt", "hello readonly", {
      config: {
        bucket: editorBucket,
        accessKeyId: editorCreds.accessKeyId,
        secretAccessKey: editorCreds.secretAccessKey
      }
    });

    if (putError) {
      console.error("Failed to write to editor workspace:", putError);
      process.exit(1);
    }

    // 5. Call createForks
    const forkPrefix = `harbor-ro-${trialId}-readonly`;
    console.log(`Creating fork with prefix: ${forkPrefix}`);
    const { data: forkData, error: forkError } = await createForks(editorBucket, 1, {
      prefix: forkPrefix,
      credentials: { role: "ReadOnly" }
    });

    if (forkError || !forkData || !forkData.forks || forkData.forks.length === 0 || !forkData.forks[0].credentials) {
      console.error("Failed to create fork:", forkError);
      process.exit(1);
    }

    const forkBucket = forkData.forks[0].bucket;
    const readonlyCreds = forkData.forks[0].credentials;

    console.log(`Fork created. Bucket: ${forkBucket}`);

    // 6. Attempt forbidden write
    console.log("Attempting forbidden write to fork bucket");
    const { error: forbiddenError } = await put("notes/forbidden.txt", "should be rejected", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey
      }
    });

    if (!forbiddenError) {
      console.error("Expected forbidden write to fail, but it succeeded!");
      process.exit(1);
    }

    console.log("Forbidden write correctly failed. Capturing error.");
    const denialMsg = `${forbiddenError.name ?? "Error"}: ${forbiddenError.message ?? String(forbiddenError)} ${JSON.stringify(forbiddenError)}`;
    await writeFile("/home/user/tigris-task/write-denial.log", denialMsg, "utf-8");

    // 7. Successful read
    console.log("Reading notes/welcome.txt from fork bucket");
    const { data: readData, error: readError } = await get("notes/welcome.txt", "string", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey
      }
    });

    if (readError || !readData) {
      console.error("Failed to read from fork bucket:", readError);
      process.exit(1);
    }

    console.log("Successfully read from fork bucket. Writing to readback.txt.");
    await writeFile("/home/user/tigris-task/readback.txt", readData, "utf-8");

    console.log("Done.");
    process.exit(0);

  } catch (err) {
    console.error("Unexpected error:", err);
    process.exit(1);
  }
}

main();

